sysauto_script.script:
(function checkDriverLicenses() {
    var usageGR = new GlideRecord('x_1794162_fuhrpark_vehicle_usage');
    usageGR.addNullQuery('usage_end');
    usageGR.query();

    var utils = new FuhrparkUtils();

    while (usageGR.next()) {
        var userId = usageGR.user.toString();
        var vehicleId = usageGR.vehicle.toString();

        var vehicleGR = usageGR.vehicle.getRefRecord();
        if (!vehicleGR || vehicleGR.check_required) continue; // Already flagged

        var isValid = utils.validateDriverLicenseForVehicle(userId, vehicleId);

        if (!isValid) {
            // 1. Mark vehicle as requiring a license check
            vehicleGR.check_required = true;
            vehicleGR.update();

            // 2. Fire event for violation
            gs.eventQueue(
                "x_1794162_fuhrpark.fuhrpark.violation.de",
                vehicleGR,
                usageGR.user.name + "",
                vehicleGR.license_plate + ""
            );
        }
    }
})();
